CREATE TABLE communities (id TEXT PRIMARY KEY CHECK (id LIKE 'community_%'), name TEXT NOT NULL) STRICT;
CREATE TABLE events (id TEXT PRIMARY KEY CHECK (id LIKE 'event_%'), community_id TEXT NOT NULL REFERENCES communities(id), name TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'draft' CHECK (state IN ('draft', 'published', 'voting', 'live', 'completed', 'archived', 'cancelled')), visibility TEXT NOT NULL DEFAULT 'public' CHECK (visibility IN ('public', 'unlisted', 'private')), participation_policy TEXT NOT NULL DEFAULT 'invite' CHECK (participation_policy IN ('invite', 'open')), UNIQUE (community_id, id)) STRICT;
CREATE TABLE guest_participations (id TEXT PRIMARY KEY CHECK (id LIKE 'participation_%'), community_id TEXT NOT NULL REFERENCES communities(id), event_id TEXT NOT NULL REFERENCES events(id), consent_scope TEXT NOT NULL DEFAULT 'event' CHECK (consent_scope = 'event'), revoked_at TEXT, UNIQUE (community_id, event_id, id), FOREIGN KEY (community_id, event_id) REFERENCES events(community_id, id)) STRICT;
CREATE TABLE canonical_songs (id TEXT PRIMARY KEY CHECK (id LIKE 'song_%'), community_id TEXT NOT NULL REFERENCES communities(id), title TEXT NOT NULL, UNIQUE (community_id, id)) STRICT;
CREATE TABLE event_song_decisions (id TEXT PRIMARY KEY CHECK (id LIKE 'decision_%'), community_id TEXT NOT NULL REFERENCES communities(id), event_id TEXT NOT NULL REFERENCES events(id), song_id TEXT NOT NULL REFERENCES canonical_songs(id), revision INTEGER NOT NULL CHECK (revision > 0), snapshot_json TEXT NOT NULL CHECK (json_valid(snapshot_json)), created_at TEXT NOT NULL, UNIQUE (event_id, song_id, revision), FOREIGN KEY (community_id, event_id) REFERENCES events(community_id, id), FOREIGN KEY (community_id, song_id) REFERENCES canonical_songs(community_id, id)) STRICT;
CREATE TABLE ballots (id TEXT PRIMARY KEY CHECK (id LIKE 'ballot_%'), community_id TEXT NOT NULL REFERENCES communities(id), event_id TEXT NOT NULL REFERENCES events(id), participation_id TEXT NOT NULL REFERENCES guest_participations(id), current_revision INTEGER NOT NULL CHECK (current_revision >= 0), state TEXT NOT NULL DEFAULT 'draft' CHECK (state IN ('draft', 'open', 'closed', 'reopened', 'final')), UNIQUE (event_id, participation_id), UNIQUE (community_id, event_id, id), FOREIGN KEY (community_id, event_id) REFERENCES events(community_id, id), FOREIGN KEY (community_id, event_id, participation_id) REFERENCES guest_participations(community_id, event_id, id)) STRICT;
CREATE TABLE ballot_versions (ballot_id TEXT NOT NULL REFERENCES ballots(id), community_id TEXT NOT NULL REFERENCES communities(id), event_id TEXT NOT NULL REFERENCES events(id), revision INTEGER NOT NULL CHECK (revision > 0), operation_id TEXT NOT NULL, rankings_json TEXT NOT NULL CHECK (json_valid(rankings_json)), created_at TEXT NOT NULL, PRIMARY KEY (ballot_id, revision), UNIQUE (community_id, operation_id), FOREIGN KEY (community_id, event_id, ballot_id) REFERENCES ballots(community_id, event_id, id)) STRICT;
CREATE TABLE proposals (id TEXT PRIMARY KEY CHECK (id LIKE 'proposal_%'), community_id TEXT NOT NULL REFERENCES communities(id), event_id TEXT NOT NULL REFERENCES events(id), participation_id TEXT NOT NULL REFERENCES guest_participations(id), title TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'submitted' CHECK (state IN ('submitted', 'moderated', 'matched', 'eligible', 'rejected', 'withdrawn')), revision INTEGER NOT NULL DEFAULT 1 CHECK (revision > 0), FOREIGN KEY (community_id, event_id) REFERENCES events(community_id, id), FOREIGN KEY (community_id, event_id, participation_id) REFERENCES guest_participations(community_id, event_id, id)) STRICT;
CREATE TABLE audit_events (id TEXT PRIMARY KEY, community_id TEXT NOT NULL REFERENCES communities(id), event_id TEXT REFERENCES events(id), actor_id TEXT NOT NULL, capability TEXT NOT NULL, operation_id TEXT NOT NULL, aggregate_type TEXT NOT NULL, aggregate_id TEXT NOT NULL, aggregate_revision INTEGER NOT NULL, occurred_at TEXT NOT NULL, UNIQUE (community_id, operation_id)) STRICT;
CREATE TABLE idempotency_receipts (community_id TEXT NOT NULL REFERENCES communities(id), operation_id TEXT NOT NULL, payload_hash TEXT NOT NULL, result_json TEXT NOT NULL CHECK (json_valid(result_json)), audit_event_id TEXT NOT NULL REFERENCES audit_events(id), created_at TEXT NOT NULL, PRIMARY KEY (community_id, operation_id)) STRICT;
CREATE TRIGGER ballot_versions_immutable_update BEFORE UPDATE ON ballot_versions BEGIN SELECT RAISE(ABORT, 'ballot history is immutable'); END;
CREATE TRIGGER ballot_versions_immutable_delete BEFORE DELETE ON ballot_versions BEGIN SELECT RAISE(ABORT, 'ballot history is immutable'); END;
CREATE TRIGGER event_song_decisions_immutable_update BEFORE UPDATE ON event_song_decisions BEGIN SELECT RAISE(ABORT, 'decision history is immutable'); END;
CREATE TRIGGER event_song_decisions_immutable_delete BEFORE DELETE ON event_song_decisions BEGIN SELECT RAISE(ABORT, 'decision history is immutable'); END;
CREATE TRIGGER participation_consent_non_broadening BEFORE UPDATE OF consent_scope ON guest_participations WHEN OLD.consent_scope = 'event' AND NEW.consent_scope <> 'event' BEGIN SELECT RAISE(ABORT, 'consent cannot be broadened implicitly'); END;
